// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;

    function setUp() public { c = new PRIVATE_ETH_CELL(); }

    function testFuzz_property(uint256 initVal, uint256 newVal, address actor) public {
        vm.assume(actor != address(0));
        initVal = bound(initVal, 0, type(uint256).max / 2);
        newVal = bound(newVal, initVal + 1, type(uint256).max);

        vm.prank(actor);
        c.SetMinSum(initVal);
        c.Initialized();

        vm.prank(actor);
        try c.SetMinSum(newVal) { /* mutant succeeds here */ } catch { /* reference reverts here */ }

        assertTrue(c.MinSum() == initVal);
    }
}
